        content: "아스테리정의 주성분은 피나스테리드(Finasteride) 1mg이에요. 피나스테리드는 5알파환원효소(5α-reductase) 2형을 억제해서 남성호르몬 테스토스테론이 DHT(디하이드로테스토스테론)로 전환되는 걸 막아줘요. DHT는 모낭을 위축시켜 탈모를 일으키는 핵심 원인 물질이에요.\n\n아스테리정은 정제 형태의 전문의약품이에요. 프로페시아와 동일한 피나스테리드 1mg 성분을 함유한 제네릭 의약품으로, 동일한 작용 기전을 가져요. 정제 표면은 코팅 처리가 돼 있어서 부서지지 않은 상태에서는 주성분과 직접 접촉되지 않아요.\n\n두타스테리드 0.5mg 제품과 달리 아스테리정은 5α-환원효소 2형만 선택적으로 억제해요. 용량을 늘려도 효과가 더 커진다는 근거는 없으므로 1일 1mg을 유지하는 게 중요해요.",
