          "짚고 갈 부분이 있어요. 식약처 허가 기준부터 짚죠. 식약처 허가 기준에서 정한 금기는 세 가지예요. 여성, 만 18세 미만 소아, 그리고 두타스테리드나 다른 5알파환원효소 억제제에 과민증이 있는 경우고요.\n\n경고 사항이 중요해요. 이 약은 피부를 통해 흡수되기 때문에 임신했거나 임신 가능성이 있는 여성이 약을 취급하면 안 돼요. 남자 태아의 생식기 발달 이상 위험 때문이에요. 소아도 누출되는 약과 접촉해선 안 되고, 접촉했다면 즉시 물과 비누로 씻어야 해요.\n\n신중히 투여해야 하는 경우도 있어요. 임신을 계획 중인 성인 남성은 생식능에 영향을 줄 수 있어 의사 판단하에 복용해야 해요. 강력한 CYP3A4 억제제(예: 리토나비르)를 만성 복용 중이라면 병용 시 주의가 필요하죠. 간 기능에 이상이 있는 환자는 약동학 자료가 없으니 처방 전 의사에게 알려야 해요. 또 이 약 복용 중에는 마지막 복용 후 최소 6개월이 지날 때까지 헌혈해서는 안 돼요.",
