        "title": "케라티딘캡슐, 잘못 먹으면 어떤 부작용이 있나요?",
        "content": "정해진 식후 복용을 지키지 않거나 빈속에 먹으면 위장 쪽 불편이 먼저 와요. 식약처 허가사항에 적힌 이상반응을 보면 위통, 구토 같은 위장관 불쾌감이 대표적이에요. 그래서 식후라는 타이밍이 단순한 권고가 아니라 위장 부담을 줄이는 장치인 셈이에요.\n\n그 밖에 허가사항이 적어둔 반응으로는 발한, 빈맥, 가려움, 두드러기, 두통, 어지럼, 홍조가 있어요. 두부 이외의 신체 부위에서 털이 나는 발모 현상이 나타나는 경우도 보고돼요. 이런 증상이 보이면 복용을 즉각 중지하고 의사 또는 약사와 상의하세요.\n\n복용량을 임의로 늘리면 이런 반응 위험이 함께 커질 수 있어요. 효과를 빨리 보겠다고 1회 2캡슐씩 먹는 식은 의미가 없고 위장 부담만 늘어요. 성인 1일 3회, 12세 이상 1일 1~2회라는 정해진 횟수를 식후에 지키는 게 부작용을 줄이는 가장 기본적인 방법이에요."
