        "title": "모나그린캡슐 가격은 얼마인가요?",
        "content": "모나그린캡슐 기준가는 한 통 15000원으로 안내돼요. 한 줄 먼저 못 박을게요. 이 15000원은 그날 약국 진열대 값이 아니라 기준가예요. 일반의약품은 약국이 들여온 도매 조건마다 표시가가 흩어져서, 매대 값이 기준선 위아래로 펼쳐지죠. 진짜 파는 값은 아래 가격 버튼에서 실거래 폭으로 확인하면 돼요. 여기서 이 약 가격을 읽는 결이 따로 있어요. 총액 15000원을 통째로 보지 말고, 한 알에 묶인 여섯을 흩어 놓고 견주는 거예요. 가령 약용효모, 케라틴, L-시스틴을 비롯한 여섯 성분을 제각각 갖추려 든다면 발품이 늘고 셈도 복잡해져요. 모나그린캡슐은 그 여섯을 한 알로 그러모아 한 값에 묶었어요. 그러니 묶음이 손해처럼 비칠지 단정하기 전에, 흩어 사 모을 때 드는 수고와 값까지 같은 저울에 올려 보세요. 그 저울에서 15000원의 무게는 사뭇 달라져요. 표시가를 견줄 때도 총액 옆에 묶음 가짓수를 꼭 붙여 두는 게 이 복합제 값을 바로 읽는 길이에요.",
